import{z as o,x as s,o as e,c as C,q as t,j as i,D as A,d as a,s as n,S as r,b as B}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"可解释性应用收束","description":"","frontmatter":{"title":"可解释性应用收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-map.md","filePath":"llm/xai-map.md","lastUpdated":1791063341000}'),p={name:"llm/xai-map.md"};function m(d,E,D,F,h,c){const l=s("Mermaid");return e(),C("div",null,[E[2]||(E[2]=t('<h1 id="可解释性应用收束" tabindex="-1">可解释性应用收束 <a class="header-anchor" href="#可解释性应用收束" aria-label="Permalink to &quot;可解释性应用收束&quot;">​</a></h1><div class="epigraph"><p>收束不是把九课再讲一遍，而是回答一个问题：周一早晨拿到一个具体需求，先打开哪一课、按什么顺序走、哪里必须停。</p><footer>—— 据 Bricken et al., 2023、Templeton et al., 2024、Elhage et al., 2021 与 Zou et al., 2023 的方法谱系，按本课程整理</footer></div><p><a href="/llm/xai-limits-frontier">上一课</a>把硬限与前沿收拢成清单。本课做收束该做的事：方法工程单元给了四件工具——字典（<a href="/llm/xai-sae-practice">第 1 课</a>）、验证协议（<a href="/llm/xai-feature-validation">第 2 课</a>）、自动化电路（<a href="/llm/xai-circuit-automation">第 3 课</a>）、表征读写（<a href="/llm/xai-representation-engineering">第 4 课</a>）；应用单元给了五个场景——监控（<a href="/llm/xai-deception-monitoring">第 5 课</a>）、训练引导（<a href="/llm/xai-guided-training">第 6 课</a>）、机制评测（<a href="/llm/xai-mechanistic-eval">第 7 课</a>）、工具链（<a href="/llm/xai-toolchain-repro">第 8 课</a>）、边界（第 9 课）。本课把它们装配成一张地图和一张决策单。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>解释性团队最贵的浪费是错配：想检测问题却去训大字典——字典是工具不是答案；想改行为却只做推理期加向量——可开关的控制挡不住有心人；想验收模型却只跑行为基准——<a href="/llm/specification-gaming">规约博弈</a>的缝隙恰好留在机制里。各场景局部最优会互相拆台：监控的探针没过验证协议（第 2 课），告警没有公信力；训练引导没跑特征画像 diff（第 6 课），伤能力不可见。收束要给的是先把需求放进哪个格子、再按什么顺序调用工具的先后表。</p><p><span class="marginnote">「字典是工具不是答案」打个比方：字典像显微镜，监控报告才是化验单。实验室花大钱买了最高倍的显微镜，不等于做出了任何诊断——检测需求要的是「用已有工具跑读数、定阈值、接人审」，而不是先造设备。错配的代价是预算烧在设备上，问题没人看。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>决策单</strong>，按「先定格子、检测先行、读数必验、误差入账」排序：</p><ol><li><strong>定格子</strong>：理解（电路）、检测（监控与评测）、改造（训练引导与读写）——三格的工具链不同，先答「要的是什么」。</li><li><strong>检测先于改造</strong>：动手之前先有读数基线，否则改造的效果与副作用都无法归因。</li><li><strong>一切读数过验证协议</strong>：探针、特征、方向，未过第 2 课验收的不进决策依据。</li><li><strong>误差与失败案例入账</strong>：误差节点占比、未找到的审计结论、验证失败清单，与正面结果同权。</li><li><strong>口径随结论走</strong>：位点、宽度、版本、字典元数据（第 1、8 课）附在任何对外结论后面。</li></ol><p>永不碰的三件事：把「欺骗方向激活」当意图判决；把未验读数写进训练目标；把解释性产出当「模型无害」的证书（第 9 课的越界）。</p><p><span class="marginnote">「检测先于改造」的道理和体检一样：先量血压、留下基线，再开始吃药；否则之后血压变化是药的功劳还是病本来就在波动，永远说不清。改模型同理——先跑特征画像和监控读数做基线，改造后的效果与副作用才有对比的参照物。</span></p>',11)),(e(),i(r,null,{default:A(()=>[n(l,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E9%9C%80%E6%B1%82%22%5D%20--%3E%20GRID%7B%22%E5%AE%9A%E6%A0%BC%E5%AD%90%22%7D%0A%20%20GRID%20--%3E%7C%E7%90%86%E8%A7%A3%7C%20CIRC%5B%22%E8%87%AA%E5%8A%A8%E5%8C%96%E7%94%B5%E8%B7%AF%EF%BC%9A%E7%B2%97%E7%AD%9B%20%2B%20%E7%BB%86%E9%AA%8C%20%2B%20%E5%B9%B2%E9%A2%84%E9%97%AD%E7%8E%AF%22%5D%0A%20%20GRID%20--%3E%7C%E6%A3%80%E6%B5%8B%7C%20MON%5B%22%E7%9B%91%E6%8E%A7%E4%B8%8E%E6%9C%BA%E5%88%B6%E8%AF%84%E6%B5%8B%EF%BC%9A%E5%88%86%E5%B1%82%E8%AF%BB%E6%95%B0%20%2B%20%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20GRID%20--%3E%7C%E6%94%B9%E9%80%A0%7C%20GUIDE%5B%22%E8%AE%AD%E7%BB%83%E5%BC%95%E5%AF%BC%EF%BC%9A%E6%95%B0%E6%8D%AE%20%2F%20%E6%8D%9F%E5%A4%B1%20%2F%20%E6%B6%88%E8%9E%8D%20%2B%20%E5%8F%8C%E9%AA%8C%E6%94%B6%22%5D%0A%20%20CIRC%20--%3E%20VAL%5B%22%E9%AA%8C%E8%AF%81%E5%8D%8F%E8%AE%AE%EF%BC%9A%E9%87%8A%E4%B9%89%20%2B%20%E5%B9%B2%E9%A2%84%20%2B%20%E5%AF%B9%E7%85%A7%22%5D%0A%20%20MON%20--%3E%20VAL%0A%20%20GUIDE%20--%3E%20VAL%0A%20%20VAL%20--%3E%20LEDGER%5B%22%E8%AF%AF%E5%B7%AE%E4%B8%8E%E5%A4%B1%E8%B4%A5%E6%A1%88%E4%BE%8B%E5%85%A5%E8%B4%A6%22%5D%0A%20%20LEDGER%20--%3E%20OUT%5B%22%E7%BB%93%E8%AE%BA%E9%99%84%E5%8F%A3%E5%BE%84%EF%BC%9A%E4%BD%8D%E7%82%B9%20%C2%B7%20%E5%AE%BD%E5%BA%A6%20%C2%B7%20%E7%89%88%E6%9C%AC%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("地图的骨架是三条不变量，与前九课一一扣合。"),B("strong",null,"不变量一：干预优先于相关。"),a(" 释义、探针、归因都先产出相关候选，升级为结论只发生在干预之后——特征验证（第 2 课）、电路闭环（第 3 课）、读写验收（第 4 课）用的是同一个闭环。"),B("strong",null,"不变量二：读数不是判决。"),a(" 内部证据始终是可证伪假设，处置要过人审与行为复核——监控（第 5 课）与机制评测（第 7 课）的判分原则同源。"),B("strong",null,"不变量三：口径绑定一切。"),a(" 位点、宽度、checkpoint、解释器版本变了，结论就换了地盘——工程实践（第 1 课）与复现规范（第 8 课）守的是这一条。三条不变量定了，字典换代、追踪器升级，决策单的顺序不动。")],-1)),(e(),i(r,null,{default:A(()=>[n(l,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20C0%5B%22%E7%9B%B8%E5%85%B3%E5%80%99%E9%80%89%EF%BC%9A%E6%8E%A2%E9%92%88%20%2F%20%E9%87%8A%E4%B9%89%20%2F%20%E5%BD%92%E5%9B%A0%22%5D%20--%3E%20G1%7B%22%E8%BF%87%E9%AA%8C%E8%AF%81%E5%8D%8F%E8%AE%AE%EF%BC%9F%EF%BC%88%E7%95%99%E5%87%BA%E9%9B%86%20%2B%20%E5%AF%B9%E7%85%A7%EF%BC%89%22%7D%0A%20%20G1%20--%3E%7C%E6%9C%AA%E8%BF%87%7C%20B1%5B%22%E5%85%A5%E5%A4%B1%E8%B4%A5%E6%B8%85%E5%8D%95%EF%BC%8C%E4%B8%8D%E4%BD%9C%E5%86%B3%E7%AD%96%E4%BE%9D%E6%8D%AE%22%5D%0A%20%20G1%20--%3E%7C%E5%B7%B2%E8%BF%87%7C%20G2%7B%22%E5%81%9A%E8%BF%87%E5%B9%B2%E9%A2%84%E5%AF%B9%E7%85%A7%EF%BC%9F%22%7D%0A%20%20G2%20--%3E%7C%E6%9C%AA%E5%81%9A%7C%20H%5B%22%E4%BB%8D%E5%8F%AA%E6%98%AF%E5%81%87%E8%AE%BE%EF%BC%9A%E5%8F%AF%E6%8E%92%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20G2%20--%3E%7C%E5%B7%B2%E5%81%9A%7C%20G3%7B%22%E4%BA%BA%E5%AE%A1%20%2B%20%E8%A1%8C%E4%B8%BA%E5%A4%8D%E6%A0%B8%EF%BC%9F%22%7D%0A%20%20G3%20--%3E%7C%E6%9C%AA%E8%BF%87%7C%20B2%5B%22%E5%9B%9E%E5%88%B0%E5%81%87%E8%AE%BE%EF%BC%8C%E6%8D%A2%E5%9F%9F%E9%87%8D%E6%B5%8B%22%5D%0A%20%20G3%20--%3E%7C%E5%B7%B2%E8%BF%87%7C%20OUT%5B%22%E5%AF%B9%E5%A4%96%E7%BB%93%E8%AE%BA%20%2B%20%E5%8F%A3%E5%BE%84%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">这张图回答「一条内部读数要过几道闸才能写进结论」：先过验证协议（它准不准），再过干预对照（它有没有因果），最后过人审与行为复核（该不该据此行动）。任何一道没过，读数仍可留着排优先级，但不能进决策依据——三条不变量在这个闸门序列里同时生效。</span></p><p><span class="marginnote">一张自检表：如果只做三件事——给高危流量挂已验证的轻量读数，把特征画像 diff 加进发布门槛，让每条对外结论自带字典元数据。多数团队在这三步内就能把解释性从演示变成工序；后面的每一步都要求先证明前面拿不出来了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张图有时效与方法界。方法界：全部工具默认白盒——有权重、能 hook、能重训；API 模型只剩行为侧的降级版。能力界：工具只见线性可读的表征，四条硬限（第 9 课）原样压在地图上，地图不承诺覆盖。时效界：字典与追踪流水线仍在换代，编号与图谱会过时，三条不变量与决策单的顺序是本课程打算留下的部分。地图之外由相邻课程接棒：模型之上的编排、工具与生产化，是 Agent 工程的主题，本课程不再跟进。</p><p><span class="marginnote">「白盒」翻译成大白话：研究者手里有模型的完整权重，能在任意一层插入钩子读取激活，甚至拿回去重新训练——相当于能拆开修理的收音机。API 模型则像密封的一次性设备，只能看到输入和输出，本课程的全部工具在它身上只剩「看行为」的降级版可用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单五步：定格子 → 检测先行 → 读数必验 → 误差入账 → 口径随结论走。</li><li>三条不变量：干预优先于相关、读数不是判决、口径绑定一切；工具换代，顺序不动。</li><li>永不碰：读数当意图判决、未验读数进训练目标、解释当无害证书。</li><li>白盒是默认前提，四条硬限压在整张地图上；解释性是纵深防御的一层，不是终点。</li><li>出处：Bricken et al., <em>Towards Monosemanticity</em>, 2023；Templeton et al., <em>Scaling Monosemanticity</em>, 2024；Elhage et al., 2021；Zou et al., 2023。</li></ul>',7))])}const u=o(p,[["render",m]]);export{g as __pageData,u as default};
